body:
{
  "pains": [
    {
      "id": "pain:phantom-violations",
      "statement": "The camera writes me up for speeding I wasn't doing, and then somebody has to sit down and get the violation taken off.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "An in-cab alert fires and a safety event lands on the driver's score for a stop he didn't roll or a speed limit that belongs to the frontage road, not the lane he is in.",
        "operational": "The driver gets called into the safety office to explain it, the safety team pulls the clip and files to have the event dismissed one event at a time, and the coaching queue fills with alerts nobody can act on.",
        "personal": "The driver spends his own time proving he was not speeding and carries a chat with Safety about driving he knows was fine."
      },
      "workflow": "The Samsara outward camera and driver app mid-run: the voice alert chimes on a frontage-road speed sign or an IN construction zone marked 'when flashing', the event lands in the fleet's safety event list, and the next morning the safety manager works the coaching queue in the dashboard and files dismissals before scores go out.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The insurer pushes cameras as the condition of the premium, so the whole fleet gets AI coaching switched on at once whether or not the settings are tuned.", "cites": ["src:6", "src:7", "src:2"] },
        { "event": "A state leaves cones and reduced-speed signs up after the work is finished, and every truck through that stretch generates violations for weeks.", "cites": ["src:6"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "It nags me about speeding when I am not (because it reads the speed limit signs on the frontage road", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "It has also nagged me about my following distance when sitting dead stopped in traffic", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "Sure we could just go peddle down, but then you hear the warnings and have to take time to explain everything to Safety to get the violation removed.", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "The other day I got called in to 'chat' with the safety guy about all the horrible rolls through stop signs and following too close that I do on a daily basis.", "cites": ["src:8"] },
            { "situation": "venting", "verbatim": "Every now and then a rolled stop will be miss called. Also, there are some discrepancies with the speed limit.", "cites": ["src:5"] }
          ],
          "costs_them": "Unpaid minutes at the end of a run arguing a machine's reading, plus a score he cannot see the evidence behind.",
          "fears": "That the false events accumulate into a record that gets him coached, disqualified or fired for driving he knows was correct.",
          "dream_outcome": "The alert only fires when he actually did something, and when it is wrong it never reaches his record in the first place."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "At times, many coaching alerts are generated that are barely actionable. If my team does not have logins or apps, scheduling behavior counseling is time-consuming.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "AI driver alerts can feel overly sensitive. Hardware troubleshooting can take extra time", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "I dont like that the driver cant be given a warning when they are following too close or when they are speeding BEFORE they get hit with the infraction.", "cites": ["src:3"] }
          ],
          "costs_them": "Hours a week triaging events that are not events, and coaching sessions to schedule for behaviour that did not happen.",
          "fears": "That drivers stop taking any alert seriously, so the real hard-brake and phone-in-hand events get shrugged off with the false ones.",
          "dream_outcome": "A queue that only contains events worth watching, and a warning to the driver before the infraction is written."
        }
      },
      "segments": ["seg:trucking", "seg:construction"],
      "feature_ref": "feat:cameras",
      "feature_note": "feat:cameras both causes and would kill this: the same AI that misreads a frontage-road sign is the thing that has to stop firing. What buyers describe wanting is a review step that catches the false event before it reaches the driver's score, and a warning to the driver before an infraction is written.",
      "cites": ["src:6", "src:3", "src:5", "src:2", "src:8"]
    },
    {
      "id": "pain:nanny-cam-in-my-face",
      "statement": "There is a lens pointed at my face all shift, I get nothing out of it, and the day it goes live is the day I start looking.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "A cab-facing camera recording video and audio all shift, and a safety score the driver cannot see the footage behind.",
        "operational": "Drivers tape over the lens, ask for their own clips and get refused because the login belongs to the company, and the experienced ones start applying elsewhere; the fleet backfills the seat.",
        "personal": "Thirty-five years on the job and being watched like a child, and a driver who likes the job starting to look again because the new safety guy plays the clips back at him."
      },
      "workflow": "The inward lens on the dash cam in the cab, the safety score in the driver app after each trip, and the walk into the safety guy's office where the clip plays on his computer and the driver has no login of his own to open it.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The fleet installs the system and tells drivers it is for insurance, without mentioning the scoring that comes with it.", "cites": ["src:7"] },
        { "event": "A rollover or serious incident, after which the office reviews the whole shift's footage rather than the event window.", "cites": ["src:7"] },
        { "event": "The safety manager changes, and the new one starts using the footage for minor events the old one ignored.", "cites": ["src:8"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Been in this job 35 years and feel I am being treated like a child", "cites": ["src:7"] },
            { "situation": "when_refusing", "verbatim": "If you want me (and my 4 million miles of experience) to leave the company, put a driver facing camera in my truck.", "cites": ["src:6"] },
            { "situation": "venting", "verbatim": "there is no upside in it for the driver with a driver facing camera. It is only there to pin stuff on you.", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "A co worker had a roll over at the end of his shift, they went back and reviewed his entire 12 hour run.", "cites": ["src:7"] },
            { "situation": "when_looking", "verbatim": "Is there any way for me to even view the videos that camera records", "cites": ["src:8"] },
            { "situation": "when_it_bites", "verbatim": "I like the job so it's hard to leave, but it's time to at least start looking again.", "cites": ["src:8"] }
          ],
          "costs_them": "The seat itself: drivers with options leave rather than be filmed, and the ones who stay lose the benefit of the doubt they used to get.",
          "fears": "That the footage exists to hang him, that it gets watched when nothing happened, and that there is no version of the story where the video helps him.",
          "dream_outcome": "Access to his own clips and his own score, and a camera that is only live when something actually happened."
        }
      },
      "segments": ["seg:trucking"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company addresses the driver's side of this. feat:workforce is coaching and training pointed at the manager. What the drivers in these three threads actually ask for is a login to their own footage and score; one whole thread is a driver asking how to see a clip of himself and being told he cannot.",
      "cites": ["src:6", "src:7", "src:8"]
    },
    {
      "id": "pain:dark-when-it-counted",
      "statement": "The one day I needed the video, the camera had timed out and there was nothing there.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Footage comes back black, trucks drop off the map when they park or run out of range, and a real accident arrives as a harsh-brake alert instead of an accident alert.",
        "operational": "Ops works the claim without the clip, chases support for replacement gateways for weeks, and checks devices by hand before trusting any report.",
        "personal": null,
        "personal_note": "No source in this sweep shows the personal rung. The reviewers write as the company about a missing clip and a replacement queue; none says what it cost them to handle an at-fault claim with no video. q:pains-personal-rung asks for it."
      },
      "workflow": "The morning after an incident, in the Samsara dashboard: pulling the clip for the insurer, finding the camera timed out or the vehicle offline since it parked, then opening a support ticket for a gateway swap and working the claim off the driver's account of it.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A collision or injury claim where the insurer asks for the footage the fleet bought the system to produce.", "cites": ["src:3", "src:2"] },
        { "event": "Gateways start failing in batches at a few years of age, and the replacement queue outruns support.", "cites": ["src:1"] }
      ],
      "who_feels": ["champion"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Recently, one of my drivers was involved in a car accident, but I did not receive an accident alert. Instead, the only notification I received was a harsh brake alert.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "Cameras time out after sitting for a duration of time. System loses trucks", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "lapses in the availability of video data from key events", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "The footage goes black sometimes. Sometimes loses connection when a driver is out of town or when the vehicle is parked for a long time.", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "out of 10 gateways requiring attention, only one has been replaced", "cites": ["src:1"] }
          ],
          "costs_them": "The claim gets argued without evidence, and the fleet pays for coverage it cannot rely on until the hardware is swapped.",
          "fears": "That the gap shows up on the worst incident, the one with an injury, and the system they championed has nothing to show.",
          "dream_outcome": "The platform tells them a camera has gone dark before a claim does, and a replacement ships in days."
        }
      },
      "segments": ["seg:trucking"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company kills this, because it is the reliability of feat:cameras and feat:telematics themselves plus the replacement path behind them. What would kill it is a device-health alert that surfaces a dark gateway the day it goes quiet, and an RMA that completes in days rather than weeks.",
      "cites": ["src:3", "src:2", "src:5", "src:1"]
    },
    {
      "id": "pain:ghosted-after-the-sale",
      "statement": "They were all over us until we signed, and now the ticket sits for weeks and I am explaining our account to a new rep again.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Tickets that go in circles, account managers who change with no notice, and replies that ask for the same troubleshooting steps already done.",
        "operational": "The fleet works around the broken thing itself, escalates by email because there is no phone number for renewals or billing, and re-explains its setup to whoever is assigned this quarter.",
        "personal": null,
        "personal_note": "No source shows the personal rung. Every reviewer here writes as the company, not the person: 'as a paying customer', 'after spending nearly 50K with them'. Nobody says what it costs the person who signed for it to keep answering for it. q:pains-champion-exposure asks for it."
      },
      "workflow": "Between the support portal and an email thread: a gateway or camera fails, the ticket is opened, the same troubleshooting steps come back, video calls with the rep never get scheduled, and renewals and billing have no number to call, so the device stays down while the thread runs.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The assigned account manager leaves or is reassigned, and account changes happen with no notice to the customer.", "cites": ["src:3", "src:2"] },
        { "event": "Hardware fails at fleet scale, so the fleet needs the vendor's process to work for ten units at once rather than one.", "cites": ["src:1"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "they are interested in selling you their product; you will be on your own after that", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "Terrible customer service; they renew contracts without notifying me.", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "Dealing with renewals and billing - there are no phone numbers to call for renewals and it is always a problem e-mailing back and forth.", "cites": ["src:3"] },
            { "situation": "when_refusing", "verbatim": "I have 6 truck with them and I'm getting ready to cancel them. They never do what they say.", "cites": ["src:9"] }
          ],
          "costs_them": "Money already spent on a system that is partly down, and management time spent chasing a vendor rather than running the fleet.",
          "fears": "That the spend keeps going out while the problem stays, and that the next renewal buys the same silence.",
          "dream_outcome": "Somebody owns the issue end to end, answers the phone, and closes it without the fleet driving the process."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "The entire process feels like we are going in circles. We are repeatedly asked to follow the same troubleshooting steps", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "when needing to talk to someone or get help with something, it's damn near impossible", "cites": ["src:4"] },
            { "situation": "when_it_bites", "verbatim": "My account manager was reassigned or left without notice. There were changes to my account that I was not notified about.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "Customer service is very slow at dealing with issues.", "cites": ["src:5"] },
            { "situation": "when_comparing", "verbatim": "in the past, I would be left wondering who I had. It would change and notice wasn't given", "cites": ["src:2"] }
          ],
          "costs_them": "Weeks of their own follow-up per issue, and a fleet that keeps asking them why the thing they brought in is still broken.",
          "fears": "That they become the vendor's support desk inside their own company.",
          "dream_outcome": "One named person who knows the account and stays, and a ticket that moves without being chased."
        }
      },
      "segments": ["seg:trucking", "seg:construction"],
      "feature_ref": null,
      "feature_note": "No feature kills this; it is the service model. Worth reading carefully: this is the loudest pain in Samsara's own review corpus, and it is also why one reviewer left Motive for Samsara, so it is the category's pain rather than one vendor's. Positioning has to decide whether to claim the other side of it.",
      "cites": ["src:1", "src:5", "src:3", "src:4", "src:9", "src:2"]
    },
    {
      "id": "pain:locked-in-three-years",
      "statement": "The contract rolled over without a word, and when we tried to get out nobody would actually cancel it.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "An invoice that arrives already renewed, a long-term commitment priced at the top of the market, and cancellation requests that do not take.",
        "operational": "Somebody has to police the renewal date themselves, argue billing line by line over email because there is no phone number, and keep paying for units the fleet no longer runs.",
        "personal": null,
        "personal_note": "No source shows what the auto-renewal costs the person who signed it. Reviewers describe the company's bill, never the conversation with their own boss about it. q:pains-champion-exposure covers this too."
      },
      "workflow": "At the renewal date in the billing thread: the invoice lands already renewed, the admin emails back and forth to fix it, and a single unit set up on the wrong billing cycle cannot be merged onto the annual invoice, so a company card gets charged monthly for one device indefinitely.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The auto-renewal date passes without notice, and the term restarts before the fleet has decided.", "cites": ["src:5", "src:3"] },
        { "event": "A cheaper or more flexible competitor quotes the fleet at renewal, which is when the exit terms get read for the first time.", "cites": ["src:2"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "they renew contracts without notifying me. They refused to review my account when I mentioned, 'I think I am being overcharged.' I keep getting the runaround.", "cites": ["src:5"] },
            { "situation": "when_comparing", "verbatim": "pricing structure is on the higher end of the market, and the long-term contract commitments", "cites": ["src:2"] },
            { "situation": "when_refusing", "verbatim": "Cancellation policy is bullshit and they don't cancel when they tell them to cancel. We refused the contract yet still held us as if we had a contract.", "cites": ["src:9"] },
            { "situation": "when_it_bites", "verbatim": "I was told by billing that they could not add the one unit to our annual invoice. Now my company credit card is billed monthly for 1 unit. It would seem to be an easy fix.", "cites": ["src:3"] }
          ],
          "costs_them": "Money leaving for hardware and seats the fleet is not using, and hours of their own time to correct a bill that should have been a phone call.",
          "fears": "That leaving is more expensive than staying, so the decision is made for them at every renewal.",
          "dream_outcome": "A term that resizes when the fleet does, a renewal that asks first, and a cancellation that completes when requested."
        }
      },
      "segments": ["seg:trucking"],
      "feature_ref": null,
      "feature_note": "Nothing in the product kills a commercial term. What ends this is a contract that shrinks with the fleet and a cancellation that completes on request. The evidence sits on both sides of the category: the sharpest quotes are the competitor's buyers, and the auto-renewal and top-of-market pricing complaints are in Samsara's own reviews.",
      "cites": ["src:5", "src:9", "src:2", "src:3"]
    },
    {
      "id": "pain:paying-for-what-we-never-turned-on",
      "statement": "It costs us a fortune and we use maybe a fifth of it, and nobody has ever sat down with us to show us the rest.",
      "element": "b2b:ease_of_doing_business:expertise",
      "shape": {
        "surface": "Modules the fleet has never opened, an upgrade path with no a la carte option, and features that used to be standard now sitting behind a paid package.",
        "operational": "People learn the parts they need by clicking around, ask for one-on-one training that does not arrive, and buy a whole tier to get the one feature they wanted.",
        "personal": "The fleet director who signed for it cannot say what half of it does, and asks for one-on-one time with someone to find out."
      },
      "workflow": "Inside the dashboard in year one: GPS and cameras get used daily, the reporting builder and service intervals never get opened, and the admin side is learned by trial and error; a new vehicle means going into settings and typing the oil-change interval in by hand, every time.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:platform",
      "triggers": [
        { "event": "A feature that used to be included moves into a paid package, which is when the fleet finds out what tier it is on.", "cites": ["src:3"] },
        { "event": "Renewal or a budget review, when somebody asks what the platform is actually doing for the money.", "cites": ["src:4"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "not knowing what all samsara has to offer in what we do. i would love to have one on one training with someone. I feel it is very expensive, but i know it does alot and helps companies.", "cites": ["src:4"] },
            { "situation": "venting", "verbatim": "The company continues to take away features that were once standard and turn them into packages that you must pay extra for.", "cites": ["src:3"] }
          ],
          "costs_them": "A large line item defended on a fraction of what it does, and upgrades bought whole to get one feature.",
          "fears": "That they are paying premium price for a commodity use of the product and cannot prove otherwise at renewal.",
          "dream_outcome": "Somebody sits with their team, shows them what applies to their work, and lets them buy only the parts they will use."
        },
        "champion": {
          "says": [
            { "situation": "when_comparing", "verbatim": "While adding features is easy, there is no a la carte option, it's a complete package upgrade when you only want to use 1 or 2 features.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "administrative side is not very user-friendly and has a steep learning curve", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "The cost can be high, especially for smaller companies, and some features take a little time to learn at first.", "cites": ["src:4"] }
          ],
          "costs_them": "Time lost relearning the admin side, and manual re-entry of settings the platform could carry forward.",
          "fears": "That the team gets blamed for under-using something expensive that nobody ever taught them.",
          "dream_outcome": "Guided setup for their actual operation, and the ability to turn on one feature without a tier change."
        }
      },
      "segments": ["seg:construction", "seg:trucking", "seg:public"],
      "feature_ref": null,
      "feature_note": "feat:platform is the thing sitting unused, so no feature kills this; enablement does. It is marked latent because nobody in these reviews calls it a problem: they call the product expensive and say they know it does a lot, then describe typing service intervals in by hand for every new vehicle as if that is normal. Seeing what feat:platform already automates is what would make them name it.",
      "cites": ["src:4", "src:3", "src:2"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers in this category write in named-tool comparisons rather than in questions about whether tooling exists. The Capterra corpus is full of switched-from lines (Geotab, Verizon Connect, Omnitracs One, Motive, Zonar, Azuga, ClearPathGPS, BigRoad, Linxup, DriveCam, Peoplenet) with a reason attached, which is a market that knows the problem and knows a field of vendors, and is choosing between them. This is the level evidenced in the two segments actually swept; seg:public is covered by this default on the strength of a single public-safety reviewer, which q:pains-public-sweep asks to fix.",
      "cites": ["src:2", "src:3"]
    },
    "seg:trucking": {
      "level": "product",
      "rationale": "Trucking buyers and drivers both name Samsara unprompted and argue its specifics rather than the category's: reviewers compare its pricing structure and contract terms against the market, and drivers in open forums name the exact hardware their company moved to and from. They know this product; what is open is price, terms and whether it is worth switching again.",
      "cites": ["src:2", "src:6"]
    }
  },
  "stats": [],
  "keywords": [
    "driver facing camera",
    "AI dash cam false alerts",
    "dash cam says I was speeding when I wasn't",
    "how to see my own samsara camera footage",
    "get a safety event removed",
    "coaching alerts not actionable",
    "camera timed out no footage",
    "gateway offline no data",
    "fleet telematics auto renewal",
    "telematics contract cancellation",
    "switching from verizon connect",
    "fleet camera driver privacy",
    "telematics pricing per vehicle a la carte"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call with your last ten closed-won fleets, what did they say was wrong today, in their words, before you showed them anything?",
      "why": "Every pain here is a hypothesis built from strangers' reviews and forum posts. A customer's own first-call sentence is the only thing that turns one into evidence, and it decides which pain leads.",
      "would_change": "pains[].confidence, pains[].statement and the order of pains[]"
    },
    {
      "id": "q:pains-churn",
      "question": "What did the fleets that left or did not renew say hurt, and how many of them named the contract or the support rather than the product?",
      "why": "Two of the six pains here (pain:ghosted-after-the-sale, pain:locked-in-three-years) come from the vendor relationship, not the workflow. If churned accounts name them too, they belong at the top of positioning's objections.",
      "would_change": "pains[].confidence on pain:ghosted-after-the-sale and pain:locked-in-three-years, and possibly a new pain row"
    },
    {
      "id": "q:pains-dismissal-rate",
      "question": "What share of AI safety events do your customers dismiss as non-events, and how many hours a week does a typical safety manager spend in the review queue?",
      "why": "pain:phantom-violations is the best-evidenced workflow pain in the map and has no number attached to it. No public figure survived the two-URL test, so the only conservative number available is yours.",
      "would_change": "stats[]"
    },
    {
      "id": "q:pains-personal-rung",
      "question": "When a fleet loses the footage for a claim, or waits weeks on a gateway swap, what does the manager say it costs them personally?",
      "why": "The personal rung is what sells, and two pains here have it null because every reviewer writes as the company. Ask a customer and it fills in.",
      "would_change": "pains[].shape.personal on pain:dark-when-it-counted and pain:ghosted-after-the-sale"
    },
    {
      "id": "q:pains-champion-exposure",
      "question": "Has a champion ever told you what it was like inside their company when the system they chose was down, or when the renewal went through without warning?",
      "why": "Two personal rungs are null for the same reason: public reviews are written in the company's voice. This is the question that gets the person's voice.",
      "would_change": "pains[].shape.personal on pain:ghosted-after-the-sale and pain:locked-in-three-years"
    },
    {
      "id": "q:pains-driver-exodus",
      "question": "Do your customers actually lose drivers over the inward-facing camera, and does anyone on their side say so out loud during the sale?",
      "why": "pain:nanny-cam-in-my-face has strong driver voice and no manager voice at all: the public record has drivers threatening to quit and no fleet manager admitting it is a rollout risk. If customers do say it, the pain gains a champion entry and the angles gain a whole stage.",
      "would_change": "pains[].who_feels and pains[].by_role on pain:nanny-cam-in-my-face"
    },
    {
      "id": "q:pains-public-sweep",
      "question": "Which public-sector fleets do you actually sell to (transit, city, schools), and where do those buyers talk to each other in public?",
      "why": "seg:public produced exactly one buyer-class voice in this sweep, a public-safety reviewer on Capterra. Review sites and trucking forums do not reach them, so the segment currently rides on the awareness default with almost nothing behind it.",
      "would_change": "pains[].segments, awareness['seg:public'], and possibly a new pain row"
    },
    {
      "id": "q:pains-equipment",
      "question": "What do construction customers say about equipment and trailers specifically: theft, after-hours movement, machines they cannot find, hours they cannot verify?",
